    exclude_disp = {20, 7, 2, 82}
    exclude_disp_str = {'20','7','07','2','02','82','expired','died','deceased','ama',
                        'left against medical advice','against medical advice',
                        'transferred','transfer to acute care','transfer acute'}

    def is_inpatient(val):
        if pd.isna(val):
            return False
        return str(val).strip().lower() in {'inpatient','ip','inpt','i'}

    def is_excluded_disp(val):
        if pd.isna(val):
            return False
        s = str(val).strip().lower()
        try:
            return int(float(s)) in exclude_disp
        except Exception:
            return s in exclude_disp_str

    ip = base[base[enc_type_col].apply(is_inpatient)].copy()
