    last_admit = base[admit_col].max()
    cutoff = last_admit - pd.Timedelta(days=30)

    denom_df = ip_eligible[ip_eligible[discharge_col] <= cutoff].copy()

    ip_all = ip.copy()

    readmit_counts = {}
    denom_counts = {}

    for dept, grp in denom_df.groupby(dept_col):
        denom_counts[dept] = len(grp)
        readmit_n = 0
        for _, row in grp.iterrows():
            pt = row[mrn_col]
            disc = row[discharge_col]
            window_start = disc + pd.Timedelta(days=1)
            window_end = disc + pd.Timedelta(days=30)
            subsequent = ip_all[
                (ip_all[mrn_col] == pt) &
                (ip_all[admit_col] >= window_start) &
                (ip_all[admit_col] <= window_end)
            ]
            if len(subsequent) > 0:
                readmit_n += 1
        readmit_counts[dept] = readmit_n

    dept_results = []
    for dept in denom_counts:
        denom = denom_counts[dept]
        numer = readmit_counts.get(dept, 0)
        rate = numer / denom if denom > 0 else float('nan')
        dept_results.append({"name": str(dept), "value": round(rate, 6)})

    dept_results_sorted = sorted(dept_results, key=lambda x: -(x['value'] if not (isinstance(x['value'], float) and np.isnan(x['value'])) else -1))[:10]

    overall_denom = len(denom_df)
    overall_numer = sum(readmit_counts.values())
