        "aggregation": "ratio",
        "label": "readmission_rate",
        "results": dept_results_sorted
    })

    result['segments'].append({
        "segment_column": dept_col,
        "metric_column": discharge_col,
        "aggregation": "ratio",
        "label": "readmission_rate_overall",
        "results": [{"name": "overall", "value": round(overall_rate, 6)}]
    })

    result['assumptions'].append(
        f"30-day readmission denominator: inpatient encounters with discharge date <= {cutoff.date()} and non-excluded disposition; n={overall_denom}"
    )
    result['assumptions'].append(
        f"Readmissions counted: {overall_numer} patients had a subsequent inpatient admit within 1-30 days of discharge"
    )
    result['assumptions'].append(
        "Excluded dispositions: expired/died/AMA/transferred (codes 2,7,20,82 and string equivalents)"
    )
    result['assumptions'].append(
        "Discharges in last 30 days of data excluded from denominator (cannot be followed)"
