        return str(val).strip().lower() in {'inpatient','ip','inpt','i'}

    def is_excluded_disp(val):
        if pd.isna(val):
            return False
        s = str(val).strip().lower()
        try:
            return int(float(s)) in exclude_disp
        except Exception:
            return s in exclude_disp_str

    ip = base[base[enc_type_col].apply(is_inpatient)].copy()
    ip = ip[ip[discharge_col].notna()].copy()
    ip_eligible = ip[~ip[disp_col].apply(is_excluded_disp)].copy()

    last_admit = base[admit_col].max()
    cutoff = last_admit - pd.Timedelta(days=30)

    denom_df = ip_eligible[ip_eligible[discharge_col] <= cutoff].copy()

    ip_all = ip[ip[admit_col].notna()].copy()

    readmit_flags = []
    for _, row in denom_df.iterrows():
        pt = row[mrn_col]
        disch = row[discharge_col]
        dept = row[dept_col]
        future = ip_all[
            (ip_all[mrn_col] == pt) &
            (ip_all[admit_col] > disch) &
            (ip_all[admit_col] <= disch + pd.Timedelta(days=30))
        ]
        readmit_flags.append({
            'MRN': pt,
            dept_col: dept,
            'readmitted': int(len(future) > 0)
        })

    readmit_df = pd.DataFrame(readmit_flags)

    if len(readmit_df) > 0:
        dept_groups = readmit_df.groupby(dept_col)
        dept_results = []
        for dept_name, grp in dept_groups:
            n = len(grp)
            r = grp['readmitted'].sum()
            rate = r / n if n > 0 else 0.0
            dept_results.append({"name": str(dept_name), "value": round(float(rate), 6)})

        dept_results_sorted = sorted(dept_results, key=lambda x: -x['value'])[:10]

        overall_rate = readmit_df['readmitted'].mean() if len(readmit_df) > 0 else 0.0

        result['segments'].append({
            "segment_column": dept_col,
            "metric_column": discharge_col,
            "aggregation": "ratio",
            "label": "readmission_rate",
            "results": dept_results_sorted
        })

        result['assumptions'].append(
            f"30-day readmission denominator: {len(denom_df)} inpatient discharges with eligible disposition and discharge >= 30 days before last admit date."
        )
        result['assumptions'].append(
            f"Overall 30-day readmission rate across all departments: {overall_rate:.4f}."
        )
        result['assumptions'].append(
            "Excluded dispositions: death, AMA, transfer (codes 20,7,2,82 and text equivalents)."
        )
        result['assumptions'].append(
            "Readmission window: next inpatient admit 1–30 days after discharge date."
        )
    else:
