    # Pending = status not yet paid/denied (not in denial denominator)
    pending_statuses = ['pending', 'pend', 'in process', 'in_process', 'submitted']
    df_valid['_status_lower'] = df_valid['Claim Status'].str.lower().str.strip()
    df_valid['_is_pending'] = df_valid['_status_lower'].isin(pending_statuses)
    df_valid['_is_denied'] = df_valid['_status_lower'].isin(['denied', 'deny', 'rejection', 'rejected', 'not covered'])

    # Per payer: distinct claim_ids
    payers = df_valid['Payer'].dropna().unique()
    denial_results = []

    for payer in payers:
        payer_df = df_valid[df_valid['Payer'] == payer]
        non_pending = payer_df[~payer_df['_is_pending']]
        total_claims = non_pending['Claim ID'].nunique()
        denied_claims = non_pending[non_pending['_is_denied']]['Claim ID'].nunique()
        rate = denied_claims / total_claims if total_claims > 0 else 0.0
        denial_results.append({"name": str(payer), "value": round(rate, 6)})

    denial_results_sorted = sorted(denial_results, key=lambda x: x['value'], reverse=True)

    result['segments'].append({
        "segment_column": "Payer",
        "metric_column": "Claim Status",
        "aggregation": "ratio",
        "label": "denial_rate",
        "results": denial_results_sorted
    })

