    claim_count_results = []
    for payer in payers:
        payer_df = df_valid[df_valid['Payer'] == payer]
        n = payer_df['Claim ID'].nunique()
        claim_count_results.append({"name": str(payer), "value": float(n)})
    claim_count_results_sorted = sorted(claim_count_results, key=lambda x: x['value'], reverse=True)

    result['segments'].append({
        "segment_column": "Payer",
        "metric_column": "Claim ID",
        "aggregation": "count",
        "label": "distinct_claims",
        "results": claim_count_results_sorted
    })

    result['assumptions'].append("Denial rate = distinct denied claim_ids / distinct non-pending claim_ids, per payer, on last-version counted rows only.")
