df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    counted_kinds = ['counted']
    df_counted = df[df['row_kind'].isin(counted_kinds)].copy()

    # Identify last version per claim_id + line
    df_counted['_version'] = df_counted['Adjustment Seq']
    df_counted = df_counted.sort_values(['Claim ID', 'Line No', '_version'])
    df_counted = df_counted.groupby(['Claim ID', 'Line No'], group_keys=False).apply(
        lambda x: x.iloc[[-1]]
    ).reset_index(drop=True)

    # Exclude voided by frequency '8'
    df_counted = df_counted[~df_counted['Claim Frequency'].astype(str).isin(['8'])]

    # Denial rate: denied / (non-pending claims)
    # Pending = Claim Status indicates pending (not denied, not paid)
    pending_statuses = ['pending', 'pend', 'in process', 'in_process', 'processing']
    df_counted['_status_lower'] = df_counted['Claim Status'].astype(str).str.lower().str.strip()
    df_counted['_is_pending'] = df_counted['_status_lower'].isin(pending_statuses)
    df_counted['_is_denied'] = df_counted['_status_lower'].isin(['denied', 'deny', 'rejection', 'rejected', 'not paid'])

    # Non-pending claims (for denominator)
    df_non_pending = df_counted[~df_counted['_is_pending']]

    # Per payer: distinct claim_ids denied / distinct claim_ids non-pending
    payers = df_non_pending['Payer'].dropna().unique()
    payer_results = []
    for payer in payers:
        payer_df = df_non_pending[df_non_pending['Payer'] == payer]
        total_claims = payer_df['Claim ID'].nunique()
        denied_claims = payer_df[payer_df['_is_denied']]['Claim ID'].nunique()
        rate = denied_claims / total_claims if total_claims > 0 else float('nan')
        payer_results.append({"name": str(payer), "value": round(rate, 6)})

    payer_results_sorted = sorted(payer_results, key=lambda x: -x['value'] if not (x['value'] != x['value']) else 0)

    result['segments'].append({
        "segment_column": "Payer",
        "metric_column": "Claim Status",
        "aggregation": "ratio",
        "label": "denial_rate",
        "results": payer_results_sorted
    })

    # Overall denial rate
    total_non_pending_claims = df_non_pending['Claim ID'].nunique()
    total_denied_claims = df_non_pending[df_non_pending['_is_denied']]['Claim ID'].nunique()
    overall_rate = total_denied_claims / total_non_pending_claims if total_non_pending_claims > 0 else float('nan')

    result['segments'].append({
        "segment_column": "Payer",
        "metric_column": "Claim Status",
        "aggregation": "ratio",
        "label": "denial_rate_overall",
        "results": [{"name": "overall", "value": round(overall_rate, 6)}]
    })

    result['assumptions'].append(
        "Denial rate = distinct denied claim_ids / distinct non-pending claim_ids, last version per claim+line only, voided excluded."
    )
    result['assumptions'].append(
        f"Denied statuses matched (case-insensitive): denied, deny, rejection, rejected, not paid. Pending excluded from denominator."
    )
    result['assumptions'].append(
        f"Total non-pending claims (denominator): {total_non_pending_claims}; total denied: {total_denied_claims}; overall denial rate: {overall_rate:.4f}."
    )

except Exception as e:
    result['anomalies'].append({
        "column": "Claim Status",
