        "segment_column": "Payer",
        "metric_column": "Claim Status",
        "aggregation": "ratio",
        "label": "denial_rate_overall",
        "results": [{"name": "overall", "value": round(overall_rate, 6)}]
    })

    result['assumptions'].append(
        f"Denial rate = distinct denied claim_ids / distinct non-pending claim_ids; overall rate = {overall_rate:.4f}"
