        {"name": str(row['Payer']), "value": float(row['Paid Amount'])}
        for _, row in payer_mean.iterrows()
    ]

    result['segments'].append({
        "segment_column": "Payer",
        "metric_column": "Paid Amount",
        "aggregation": "mean",
        "label": None,
        "results": payer_mean_results
    })

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)[:120]}")

