try:
    counted_mask = df['row_kind'] == 'counted'
    df_counted = df[counted_mask].copy()

    seg_col = 'CPT/HCPCS'
    metric_col = 'Paid Amount'

    df_seg = df_counted[[seg_col, metric_col]].dropna(subset=[seg_col, metric_col])

    top_groups = df_seg.groupby(seg_col)[metric_col].sum().nlargest(10)

    seg_results = [{"name": str(name), "value": float(val)} for name, val in top_groups.items()]

    result['segments'].append({
        "segment_column": seg_col,
        "metric_column": metric_col,
        "aggregation": "sum",
        "label": "total_paid_by_procedure",
        "results": seg_results
    })

    top_groups_count = df_seg.groupby(seg_col)[metric_col].count().reindex(top_groups.index)
    count_results = [{"name": str(name), "value": float(val)} for name, val in top_groups_count.items()]

    result['segments'].append({
        "segment_column": seg_col,
        "metric_column": metric_col,
        "aggregation": "count",
        "label": "claim_line_count_by_procedure",
        "results": count_results
    })

    top_groups_mean = df_seg.groupby(seg_col)[metric_col].mean().reindex(top_groups.index)
    mean_results = [{"name": str(name), "value": float(val)} for name, val in top_groups_mean.items()]

    result['segments'].append({
        "segment_column": seg_col,
        "metric_column": metric_col,
        "aggregation": "mean",
        "label": "avg_paid_per_line_by_procedure",
        "results": mean_results
    })

    total_paid = df_seg[metric_col].sum()
    if total_paid > 0:
        share_results = [{"name": str(name), "value": float(val / total_paid)} for name, val in top_groups.items()]
        result['segments'].append({
            "segment_column": seg_col,
            "metric_column": metric_col,
            "aggregation": "ratio",
            "label": "paid_share_by_procedure",
            "results": share_results
        })

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

